return items.map(item => {
  const d = item.json;

  return {
    json: {
      conflict: {
        conflict_id: d.conflict_id,
        severity: d.conflict_severity,
        status: d.conflict_status,
        week_start_date: d.week_start_date,
        overallocation_hours: Number(d.overallocation_hours),
      },

      resource: {
        resource_id: d.resource_id,
        resource_name: d.resource_name,
        role: d.role,
        department: d.department,
      },

      capacity: {
        available_hours: Number(d.capacity_hours),
        baseline_demand_hours: Number(d.baseline_demand_hours),
        baseline_utilization_pct: Number(d.baseline_utilization_pct),
      },

      recommended_scenario: {
        scenario_id: d.scenario_id,
        scenario_name: d.scenario_name,
        scenario_demand_hours: Number(d.scenario_demand_hours),
        scenario_utilization_pct: Number(d.scenario_utilization_pct),
        scenario_outcome: d.scenario_outcome,
        effectiveness_score: Number(d.effectiveness_score),
        governance_score: Number(d.governance_score),
        overall_recommendation_score: Number(
          d.overall_recommendation_score
        ),
        recommendation_rank: Number(d.recommendation_rank),
      },

      governance: {
        approval_role: d.approval_role,
        escalation_hours: d.escalation_hours
          ? Number(d.escalation_hours)
          : null,
      },

      affected_activities: Array.isArray(d.affected_activities)
        ? d.affected_activities
        : [],

      proposed_changes: Array.isArray(d.proposed_changes)
        ? d.proposed_changes
        : [],
    }
  };
});

return items.map(item => {
  const raw = item.json.output;

  if (!raw) {
    throw new Error('AI output is empty');
  }

  let parsed;

  try {
    parsed = JSON.parse(raw);
  } catch (error) {
    throw new Error(`AI output is not valid JSON: ${error.message}`);
  }

  const requiredFields = [
    'executive_summary',
    'conflict_explanation',
    'recommended_action',
    'recommendation_rationale',
    'residual_risk',
    'governance_action',
    'management_commentary'
  ];

  for (const field of requiredFields) {
    if (typeof parsed[field] !== 'string' || parsed[field].trim() === '') {
      throw new Error(`Missing or invalid field: ${field}`);
    }
  }

  return {
    json: parsed
  };
});

