parameters.jsCode:
const allItems = $input.all().map(item => item.json);

const summary = allItems.find(item =>
  Object.prototype.hasOwnProperty.call(
    item,
    'total_available_capacity_hours'
  )
);

const governanceActivity = allItems.find(item =>
  Object.prototype.hasOwnProperty.call(
    item,
    'recommendations_created'
  )
);

const exceptions = allItems.filter(item =>
  Object.prototype.hasOwnProperty.call(
    item,
    'resource_id'
  )
);

if (!summary) {
  throw new Error('Weekly portfolio capacity summary not found');
}

if (!governanceActivity) {
  throw new Error('Weekly governance activity not found');
}

const governanceWeekStart =
  $node["Get Governance Reporting Period"].json.governance_week_start;

return [
  {
    json: {
      report: {
        report_type: 'WEEKLY_RESOURCE_CAPACITY_REPORT',

        capacity_week_start: summary.week_start_date,
        governance_week_start: governanceWeekStart,

        portfolio: {
          total_available_capacity_hours:
            Number(summary.total_available_capacity_hours),

          total_demand_hours:
            Number(summary.total_demand_hours),

          portfolio_utilization_pct:
            Number(summary.portfolio_utilization_pct),

          overloaded_resources:
            Number(summary.overloaded_resources),

          critical_resources:
            Number(summary.critical_resources)
        },

        governance_current_state: {
          pending_approvals:
            Number(summary.pending_approvals),

          approved_mitigations:
            Number(summary.approved_mitigations),

          rejected_mitigations:
            Number(summary.rejected_mitigations),

          conflicts_without_decision:
            Number(summary.conflicts_without_decision)
        },

        governance_activity: {
          recommendations_created:
            Number(governanceActivity.recommendations_created),

          decisions_approved:
            Number(governanceActivity.decisions_approved),

          decisions_rejected:
            Number(governanceActivity.decisions_rejected),

          decisions_touched:
            Number(governanceActivity.decisions_touched),

          conflicts_touched:
            Number(governanceActivity.conflicts_touched),

          governance_events:
            Number(governanceActivity.governance_events)
        },

        exceptions: exceptions.map(e => ({
          resource_id: e.resource_id,
          resource_name: e.resource_name,
          role: e.role,
          department: e.department,

          available_hours:
            Number(e.available_hours),

          demand_hours:
            Number(e.demand_hours),

          utilization_pct:
            Number(e.utilization_pct),

          overallocation_hours:
            Number(e.overallocation_hours),

          severity: e.severity,

          conflict_id: e.conflict_id,
          conflict_status: e.conflict_status,

          approval_status: e.approval_status,
          governance_status: e.governance_status,

          decision_owner: e.decision_owner,
          decision_date: e.decision_date
        }))
      }
    }
  }
];

const reportId =
  Number($node["Store Weekly Capacity Snapshot"].json.report_id);

const exceptions =
  $node["Build Weekly Capacity Report Payload"].json.report.exceptions;

return exceptions.map(e => ({
  json: {
    report_id: reportId,
    resource_id: e.resource_id,
    conflict_id: e.conflict_id ? Number(e.conflict_id) : null,
    utilization_pct: Number(e.utilization_pct),
    overallocation_hours: Number(e.overallocation_hours),
    severity: e.severity,
    governance_status: e.governance_status,
    decision_status: e.approval_status || null
  }
}));

